import java.util.Arrays;

public class ReferenceDemo {
    static void change(int[] x) {
        x[0] = 10;
        x = new int[]{1, 2};
    }
    public static void main(String[] args) {
        int[] scores = {6, 8};
        change(scores);
        System.out.println(Arrays.toString(scores)); // [10, 8]
    }
}

